Ext._define('apd.homologation.HomologationWindow', {
    extend: 'core.RestfulWindow',

    rest: 'apd.homologation.HomologationRestful',

    width: 800,

    height: 550,

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                {
                    xtype: 'hidden',
                    name: 'pk',
                    value: cfg.params.pk
                },
                {
                    xtype: "rest-autocompletefield", 
                    fieldLabel: "Publica\u00e7\u00e3o", 
                    allowBlank: false, 
                    rest: "rh.publicacao.Restful", 
                    name: "publication"
                }, 
                {
                    title: 'Considerações',
                    flex: 1,
                    border: false,
                    height:430,
                    items: [
                        {
                            allowBlank: true,
                            name: "text",
                            height:295,
                            xtype: "ckeditor"
                        },
                    ]
                },
            ]
            });

        return this._formPanel;
    },


    save: function(){
        var form = this.getFormPanel().getForm();
        var rest = Ext._create('apd.homologation.HomologationRestful', {});
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        mask.show();
        rest.doRequest(
            rest.getRoute('homologation_apd', false, 'POST', {
                scope: this,
                params: {
                    pk: form.getValues().pk,
                    publication: form.getValues().publication,
                    text: form.getValues().text,
                },
                callback: function() {
                    mask.hide();
                    mask = undefined;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success) {
                        this.resource.getStore().reload()
                        this.destroy();
                    }
                    else
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function(xhr) {
                    Ext.Msg.show({
                        title: 'Atenção',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponível no momento.'
                    });
                },
            })
        );
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        // console.debug(cfg);

        Ext.applyIf(cfg, {
            'disableSaveAndNew': true,
        });

        apd.homologation.HomologationWindow.superclass.constructor.call(this, cfg);
    },
    
});

